courseData.go = {
	"Getting Started": {
		"What is Go": { exp: "Go is a compiled, statically-typed language designed for simplicity, concurrency, and fast execution. Built by Google for systems programming and microservices.", code: "package main\nimport \"fmt\"\nfunc main() {\n\tfmt.Println(\"Hello, Go!\")\n}" },
		"Go Syntax": { exp: "Go syntax emphasizes clarity and brevity. Uses curly braces for blocks and semicolons are optional. Comments use // or /* */.", code: "// Single line comment\n/* Multi-line\n   comment */" },
		"Your First Program": { exp: "Every Go program starts with a package declaration and a main() function for executables.", code: "package main\nfunc main() {\n\tprintln(\"Welcome to Go\")\n}" },
		"Go Playground": { exp: "The Go Playground (go.dev/play) lets you write, run, and share Go code in your browser. Great for experimentation and sharing bug repros.", code: "// Try it at https://go.dev/play\npackage main\nimport \"fmt\"\nfunc main() {\n\tfmt.Println(\"Playground ready\")\n}" },
		"go run vs go build": { exp: "go run compiles and runs a program without producing a binary. go build produces a standalone executable in the current directory.", code: "# Run directly (no binary)\ngo run main.go\n\n# Build an executable\n# Produces ./program (or .exe on Windows)\ngo build -o program main.go" },
		"GOPATH & Module Basics": { exp: "GOPATH was the original workspace location. Modern Go uses modules (go mod) instead. GOPATH is still used for global binary installs via go install.", code: "export GOPATH=$HOME/go\n# Install a tool globally\ngo install golang.org/x/tools/cmd/goimports@latest\n# Installed binaries go to $GOPATH/bin" }
	},
	"Variables & Types": {
		"Variable Declaration": { exp: "Declare variables using var, const, or short declaration (:=). Types can be explicit or inferred.", code: "var name string = \"Doge\"\nconst pi = 3.14\ncount := 42" },
		"Primitive Types": { exp: "Go includes bool, string, int, uint, float32, float64, complex64, and more. Integer types have fixed sizes (int8, int16, int32, int64).", code: "var active bool = true\nvar score int64 = 1000\nvar ratio float32 = 2.5\nvar c complex128 = 1 + 2i" },
		"Type Conversion": { exp: "Explicitly convert between compatible types using T(value) syntax. Go does NOT do implicit type conversion.", code: "var x int = 42\nvar y float64 = float64(x)\nvar s string = string(rune(65)) // \"A\"" },
		"Constants": { exp: "Constants are immutable values that must be known at compile time. Use const keyword with iota for enumerated constants.", code: "const Pi = 3.14159\nconst MaxPlayers = 100\n\nconst (\n\tStatusOK = iota // 0\n\tStatusErr       // 1\n)" },
		"Zero Values": { exp: "Variables declared without an explicit initial value are assigned a zero value: 0 for numbers, false for bool, \"\" for strings, nil for pointers/slices/maps/channels/interfaces.", code: "var i int     // 0\nvar f float64 // 0\nvar b bool    // false\nvar s string  // \"\"\nvar p *int    // nil\nfmt.Println(i, f, b, s, p)" },
		"Short Declaration (:=)": { exp: "Use := inside functions for type-inferred variable declaration and assignment. Cannot use at package level. At least one variable on left must be new.", code: "name := \"Alice\"\nage := 30\n// Re-declaration with new variable\nage, year := 31, 2026 // age reassigned, year new" },
		"Type Inference": { exp: "Go infers types from the right-hand side of := or var declarations. Untyped numeric constants get default types (int, float64, complex128) when needed.", code: "x := 42       // int\npi := 3.14    // float64\nc := 1 + 2i   // complex128\n\nvar y float64 = 3\nz := y         // z is float64 (inferred from y)" }
	},
	"Operators": {
		"Arithmetic Operators": { exp: "Standard math: +, -, *, /, %. Go supports ++ and -- but only as statements, not expressions.", code: "x := 10 + 5\ny := 20 - 3\nz := 4 * 5\nq := 20 / 4\nr := 17 % 5\nx++ // statement, OK\n// y = x++ // compile error" },
		"Comparison Operators": { exp: "Compare values using ==, !=, <, >, <=, >=. Return boolean results. Valid for comparable types.", code: "5 > 3   // true\n5 == 5  // true\n5 != 3  // true\n\"a\" < \"b\" // true (lexicographic)" },
		"Logical Operators": { exp: "Combine booleans with &&, ||, and !. Short-circuit evaluation is supported: && stops on first false, || stops on first true.", code: "if x > 0 && y < 10 {\n\tfmt.Println(\"Both true\")\n}\nif !done {\n\tfmt.Println(\"Not done\")\n}" },
		"Bitwise Operators": { exp: "Manipulate bits using &, |, ^, <<, >>, and &^ (AND NOT, a.k.a. bit clear).", code: "a := 5      // 0101\nb := 3      // 0011\nc := a & b  // 0001 = 1\nd := a | b  // 0111 = 7\ne := a ^ b  // 0110 = 6\nf := a &^ b // 0100 = 4 (clear bits set in b)" },
		"Increment/Decrement Statements": { exp: "++ and -- are statements, not expressions. They cannot be used in assignments or comparisons. Only postfix notation is allowed.", code: "i := 0\ni++          // OK: statement\n// j := i++  // ERROR: not an expression\n// if i++ > 0 {} // ERROR\nfor i < 5 {\n\ti++\n\tfmt.Println(i)\n}" },
		"Operator Precedence": { exp: "Go operator precedence from highest to lowest: *, /, %, <<, >>, &, &^; then +, -, |, ^; then ==, !=, <, <=, >, >=; then &&; then ||. Use parentheses to clarify.", code: "x := 2 + 3 * 4   // 14 (not 20)\ny := (2 + 3) * 4 // 20\nz := 1<<2 + 3    // 7 (shift before add)" }
	},
	"Control Flow": {
		"If & Else": { exp: "Standard conditional branching. Parentheses are optional; braces are required. If can include a short statement before the condition.", code: "if x > 10 {\n\tfmt.Println(\"Greater\")\n} else if x > 5 {\n\tfmt.Println(\"Medium\")\n} else {\n\tfmt.Println(\"Lesser\")\n}\n\nif err := doWork(); err != nil {\n\tfmt.Println(err)\n}" },
		"Switch Statement": { exp: "Multi-way branching on a single expression. Cases don't fall through by default. Use fallthrough keyword explicitly when needed.", code: "switch day {\ncase \"Monday\":\n\tfmt.Println(\"Work day\")\ncase \"Saturday\", \"Sunday\":\n\tfmt.Println(\"Weekend\")\ndefault:\n\tfmt.Println(\"Other day\")\n}" },
		"For Loop": { exp: "Go has only one loop construct. Use for with init, condition, and post, or as while/infinite loop.", code: "// Traditional for\nfor i := 0; i < 5; i++ {\n\tfmt.Println(i)\n}\n// While-style\nfor i < 10 { i++ }\n// Infinite\nfor { break }" },
		"Break & Continue": { exp: "Exit loops early with break or skip to next iteration with continue. Labels let you break/continue outer loops.", code: "for i := 0; i < 10; i++ {\n\tif i == 2 { continue }\n\tif i == 5 { break }\n\tfmt.Println(i)\n}" },
		"Label Statements": { exp: "Labels mark a position in code for break, continue, or goto. Use them to exit or continue outer loops from nested inner loops.", code: "outer:\nfor i := 0; i < 3; i++ {\n\tfor j := 0; j < 3; j++ {\n\t\tif i*j > 2 {\n\t\t\tbreak outer\n\t\t}\n\t\tfmt.Printf(\"%d,%d \", i, j)\n\t}\n}\n// Output: 0,0 0,1 0,2 1,0 1,1 1,2" },
		"Type Switch": { exp: "A switch that asserts the dynamic type of an interface value. Each case specifies a type. Useful with interface{} or any.", code: "var v any = 42\nswitch t := v.(type) {\ncase int:\n\tfmt.Printf(\"int: %d\\n\", t)\ncase string:\n\tfmt.Printf(\"string: %s\\n\", t)\ndefault:\n\tfmt.Printf(\"unknown: %T\\n\", t)\n}" },
		"Defer": { exp: "Defer postpones a function call until the surrounding function returns. Deferred calls are executed in LIFO order. Arguments are evaluated immediately.", code: "func main() {\n\tdefer fmt.Println(\"first defer\")\n\tdefer fmt.Println(\"second defer\")\n\tfmt.Println(\"work\")\n}\n// Output: work, second defer, first defer" },
		"Goto": { exp: "Goto jumps to a labeled statement within the same function. Cannot jump over variable declarations or into blocks. Use sparingly.", code: "i := 0\nloop:\nif i < 3 {\n\tfmt.Println(i)\n\ti++\n\tgoto loop\n}" }
	},
	"Functions": {
		"Function Declaration": { exp: "Define functions with func keyword. Specify parameter types and return types explicitly.", code: "func greet(name string) string {\n\treturn \"Hello, \" + name\n}" },
		"Multiple Return Values": { exp: "Functions can return multiple values. Commonly used for (result, error) pattern.", code: "func divide(a, b float64) (float64, error) {\n\tif b == 0 {\n\t\treturn 0, errors.New(\"division by zero\")\n\t}\n\treturn a / b, nil\n}" },
		"Named Return Values": { exp: "Name return values for cleaner code. They act as variables initialized to zero values. A bare return returns the current values of named returns.", code: "func swap(x, y string) (a, b string) {\n\ta = y\n\tb = x\n\treturn\n}" },
		"Variadic Functions": { exp: "Accept variable number of arguments using ... syntax. Creates a slice of the arguments. Only the last parameter can be variadic.", code: "func sum(nums ...int) int {\n\ttotal := 0\n\tfor _, n := range nums {\n\t\ttotal += n\n\t}\n\treturn total\n}\nfmt.Println(sum(1, 2, 3)) // 6" },
		"Anonymous Functions & Closures": { exp: "Functions without a name assigned to variables or passed directly. Closures capture surrounding variables by reference, not by value.", code: "multiply := func(x, y int) int {\n\treturn x * y\n}\nfmt.Println(multiply(3, 4))\n\ncounter := func() func() int {\n\tcount := 0\n\treturn func() int {\n\t\tcount++\n\t\treturn count\n\t}\n}()\nfmt.Println(counter()) // 1\nfmt.Println(counter()) // 2" },
		"init Functions": { exp: "init() runs automatically when a package is initialized, before main(). Multiple init() calls in a file run in order; across files they run in lexical order. No parameters or return values.", code: "var dbConn *sql.DB\n\nfunc init() {\n\tvar err error\n\tdbConn, err = sql.Open(\"postgres\", dsn)\n\tif err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tlog.Println(\"db initialized\")\n}" },
		"Function Values": { exp: "Functions are first-class values in Go. They can be assigned to variables, passed as arguments, and returned from other functions (higher-order functions).", code: "// Function as argument\nfunc apply(a, b int, op func(int, int) int) int {\n\treturn op(a, b)\n}\n\nadd := func(a, b int) int { return a + b }\nfmt.Println(apply(3, 4, add)) // 7\n\n// Function returning function\nfunc makeAdder(x int) func(int) int {\n\treturn func(y int) int { return x + y }\n}\nadd5 := makeAdder(5)\nfmt.Println(add5(10)) // 15" }
	},
	"Collections": {
		"Arrays": { exp: "Fixed-size sequences with homogeneous elements. Size is part of the type ([3]int != [4]int). Passed by value (copied) when assigned or passed to functions.", code: "var scores [5]int\nscores[0] = 95\ntemps := [3]float64{98.6, 99.2, 101.3}\n// [...] infers size from initializer\nvals := [...]int{1, 2, 3}" },
		"Slices": { exp: "Dynamic-length views backed by an underlying array. Slice expression [low:high] creates a view into an existing array or slice without copying data.", code: "nums := []int{1, 2, 3, 4, 5}\npart := nums[1:4]  // [2, 3, 4]\nnums = append(nums, 6) // may allocate new backing array\nfmt.Println(len(nums), cap(nums))" },
		"Slice Internals": { exp: "A slice is a descriptor: pointer to underlying array, length, capacity. Append grows by doubling the capacity up to 1024, then ~25% growth. Slicing beyond len but within cap reuses the backing array.", code: "s := make([]int, 3, 5) // len=3, cap=5\ns2 := s[:5]            // extends view to cap\ns[0] = 10\nfmt.Println(s2[0])      // 10 (same backing array)\n\ncopy(s2, []int{1,2,3,4,5}) // copy elements" },
		"Maps": { exp: "Unordered key-value collections built on hash tables. Keys must be comparable types (== works). Maps are reference types; zero value is nil.", code: "ages := map[string]int{\n\t\"Doge\": 5,\n\t\"Buddy\": 3,\n}\nages[\"Max\"] = 7\ndelete(ages, \"Buddy\")\n\n// Two-value lookup\nval, ok := ages[\"Unknown\"]\nif !ok {\n\tfmt.Println(\"key not found\")\n}" },
		"Range Loops": { exp: "Iterate with range over slices, maps, strings, channels. For slices: returns index, value. For maps: returns key, value. For strings: returns byte index, rune.", code: "for i, v := range []int{10, 20, 30} {\n\tfmt.Println(i, v)\n}\nfor key, value := range ages {\n\tfmt.Println(key, value)\n}\n// Skip index with _\nfor _, v := range items { fmt.Println(v) }" },
		"make vs new": { exp: "make(T, args) creates slices, maps, and channels (initialized, ready to use). new(T) allocates zero value and returns *T. make returns T (not *T).", code: "s := make([]int, 5)    // slice ready to use\nm := make(map[int]string) // map ready for insertion\n\np := new(int)    // *int pointing to 0\n*p = 42\nfmt.Println(*p)\n\n// new for struct\nu := new(User)   // *User with zero fields" }
	},
	"Pointers & References": {
		"Pointer Basics": { exp: "Pointers hold memory addresses. Use & to get a variable's address and * to dereference (read or write through the pointer). Zero value is nil.", code: "x := 42\np := &x         // p points to x, type *int\nfmt.Println(*p) // 42 (dereference)\n*p = 100        // changes x to 100\nfmt.Println(x)  // 100" },
		"Pointers to Structs": { exp: "Access struct fields through pointers using dot notation. Go automatically dereferences struct pointers for field access.", code: "type Person struct { Name string }\np := &Person{\"Alice\"}\np.Name = \"Bob\"  // Go translates to (*p).Name = \"Bob\"\nfmt.Println(p.Name)" },
		"Pointers as Parameters": { exp: "Go is pass-by-value. Use pointers to allow a function to modify its caller's data, or to avoid copying large structs.", code: "func increment(n *int) {\n\t*n++\n}\nval := 5\nincrement(&val)  // val becomes 6\n\nfunc update(u *User) {\n\tu.Name = \"Updated\"\n}" },
		"new() Function": { exp: "new(T) allocates zero-value storage for T and returns *T. It never returns nil. Equivalent to &T{} for structs. Use when you need a pointer to a zero-valued instance.", code: "p := new(int)\nfmt.Println(*p) // 0\n\nm := new(map[string]int)\n// *m is nil! new doesn't initialize maps/slices\n// Use make() for maps, slices, channels instead\n\ntype Config struct { Port int }\nc := new(Config)\nc.Port = 8080 // same as (*c).Port = 8080" },
		"Pointer vs Value Receiver": { exp: "Use pointer receiver (*T) when the method modifies the receiver, or when the struct is large. Use value receiver (T) for small, immutable types. Pointer receiver avoids copying on each call.", code: "type Counter struct{ N int }\n\n// Value receiver: operates on copy\nfunc (c Counter) Value() int { return c.N }\n\n// Pointer receiver: modifies original\nfunc (c *Counter) Inc() { c.N++ }\n\nc := Counter{5}\nc.Inc()\nfmt.Println(c.Value()) // 6" }
	},
	"Structs & Composition": {
		"Struct Definition": { exp: "Group related fields into a struct type. Exported fields start with uppercase letter for visibility across packages.", code: "type User struct {\n\tID    int\n\tName  string\n\tEmail string\n}\nuser := User{ID: 1, Name: \"Alice\", Email: \"alice@example.com\"}" },
		"Struct Tags": { exp: "Struct tags are metadata strings attached to fields, commonly used by encoding/json, validation libraries, and ORMs. Tags appear after the field type in backticks.", code: "type Config struct {\n\tHost string `json:\"host\" yaml:\"host\"`\n\tPort int    `json:\"port\" default:\"8080\"`\n\tEnv  string `json:\"-\"` // \"-\" omits from JSON\n}\n\n// Tags accessed via reflect\nfield, _ := reflect.TypeOf(Config{}).FieldByName(\"Host\")\nfmt.Println(field.Tag.Get(\"json\")) // \"host\"" },
		"Anonymous (Embedded) Fields": { exp: "Embed types without a field name. Their methods and fields are promoted to the embedding struct. Not inheritance, but composition.", code: "type Person struct {\n\tName string\n\tAge  int\n}\ntype Employee struct {\n\tPerson          // embedded, promoted fields\n\tID      int\n\tCompany string\n}\n\ne := Employee{Person: Person{\"Alice\", 30}, ID: 1, Company: \"Acme\"}\nfmt.Println(e.Name) // promoted from Person" },
		"Struct Methods": { exp: "Attach methods to types using receiver syntax. Methods are functions with a receiver parameter between func and method name.", code: "type Circle struct { Radius float64 }\nfunc (c Circle) Area() float64 {\n\treturn math.Pi * c.Radius * c.Radius\n}\n\nc := Circle{Radius: 5}\nfmt.Println(c.Area())" },
		"Pointer Receivers": { exp: "Pointer receiver allows modification of the struct. Value receiver works on a copy. Consistency: if any method has pointer receiver, all should.", code: "type Circle struct { Radius float64 }\n\n// Pointer receiver modifies original\nfunc (c *Circle) Scale(factor float64) {\n\tc.Radius *= factor\n}\n\nc := Circle{Radius: 5}\nc.Scale(2)\nfmt.Println(c.Radius) // 10" },
		"Struct Comparison": { exp: "Structs with only comparable fields (no slices, maps, or functions) can be compared with == and used as map keys.", code: "type Point struct {\n\tX, Y int\n}\na := Point{1, 2}\nb := Point{1, 2}\nfmt.Println(a == b) // true\n\n// Not comparable (contains slice)\n// type Bad struct { Items []int }" },
		"Constructor Functions": { exp: "Go has no constructors. Use factory functions (NewXxx or New) that return a pointer to a struct, optionally performing validation or initialization.", code: "type Config struct {\n\tHost string\n\tPort int\n}\n\nfunc NewConfig(host string, port int) (*Config, error) {\n\tif host == \"\" {\n\t\treturn nil, errors.New(\"host required\")\n\t}\n\tif port <= 0 {\n\t\tport = 8080\n\t}\n\treturn &Config{Host: host, Port: port}, nil\n}" }
	},
	"Interfaces": {
		"Interface Definition": { exp: "Define interfaces as a set of method signatures. Any type implementing all methods implicitly satisfies the interface. Interfaces are satisfied implicitly.", code: "type Reader interface {\n\tRead([]byte) (int, error)\n}\ntype Writer interface {\n\tWrite([]byte) (int, error)\n}" },
		"Implicit Implementation": { exp: "Go uses structural typing. A type satisfies an interface simply by implementing its methods. No explicit declaration like 'implements' is needed.", code: "type File struct{}\nfunc (f File) Read(p []byte) (int, error) { return len(p), nil }\n// File implicitly satisfies io.Reader\n\nvar r io.Reader = File{}\nbuf := make([]byte, 10)\nr.Read(buf)" },
		"Type Assertions": { exp: "Extract the concrete value from an interface using value.(Type). The two-value form prevents panics: val, ok := x.(Type).", code: "var r interface{} = \"hello\"\ns := r.(string)         // panics if wrong type\nn, ok := r.(int)        // ok=false, n=0 (safe)\n\nif s, ok := r.(string); ok {\n\tfmt.Println(\"string:\", s)\n}" },
		"Empty Interface (any)": { exp: "interface{} (or 'any' in Go 1.18+) accepts values of any type. Used before generics for containers. Now used when truly any type is needed.", code: "var empty any\nempty = \"string\"\nempty = 42\nempty = []int{1, 2, 3}\n\nfunc PrintAll(vals []any) {\n\tfor _, v := range vals {\n\t\tfmt.Println(v)\n\t}\n}" },
		"Interface Composition": { exp: "Combine interfaces by embedding them in a new interface. A type must implement all embedded interfaces' methods to satisfy the composed interface.", code: "type Reader interface { Read([]byte) (int, error) }\ntype Writer interface { Write([]byte) (int, error) }\ntype Closer interface { Close() error }\n\n// Composed interface\ntype ReadWriteCloser interface {\n\tReader\n\tWriter\n\tCloser\n}" },
		"Interface Values & Nil": { exp: "An interface value is a (type, value) pair. An interface is nil only when both the type and value are nil. A nil pointer inside a non-nil interface is not nil!", code: "var buf *bytes.Buffer = nil\nvar w io.Writer = buf  // type=*bytes.Buffer, value=nil\n\n// w != nil even though underlying pointer is nil\nif w != nil {\n\tw.Write([]byte(\"hi\")) // PANIC: nil pointer dereference\n}\n\n// Fix: check both\nfunc safeWrite(w io.Writer) {\n\tif w == nil { return }\n\tw.Write([]byte(\"ok\"))\n}" },
		"Best Practices (Accept interfaces, return structs)": { exp: "Accept interfaces to allow flexibility from callers; return concrete types so callers can access fields and methods without type assertions.", code: "// Accept interface\nfunc Process(r io.Reader) error {\n\tdata, _ := io.ReadAll(r)\n\treturn processData(data)\n}\n\n// Return concrete type\nfunc NewHandler() *Handler {\n\treturn &Handler{pool: &sync.Pool{}}\n}" }
	},
	"Error Handling": {
		"Error Interface": { exp: "Errors are values implementing the built-in error interface: Error() string. Functions return nil to indicate success.", code: "type error interface {\n\tError() string\n}\nvar err error = nil\n\nfunc Divide(a, b float64) (float64, error) {\n\tif b == 0 {\n\t\treturn 0, errors.New(\"division by zero\")\n\t}\n\treturn a / b, nil\n}" },
		"Error Checking": { exp: "Idiomatic Go checks errors immediately. Use guard clauses for early returns. Handle errors once — don't ignore or handle them multiple times.", code: "val, err := doWork()\nif err != nil {\n\tfmt.Println(\"Error:\", err)\n\treturn\n}\nfmt.Println(val)\n\n// Immediate handling is preferred\nf, err := os.Open(file)\nif err != nil {\n\treturn fmt.Errorf(\"open: %w\", err)\n}\ndefer f.Close()" },
		"Custom Error Types": { exp: "Create custom error types by implementing the Error() string method. Custom types carry additional context for callers to inspect.", code: "type ValidationError struct {\n\tField string\n\tValue any\n\tMsg   string\n}\n\nfunc (e *ValidationError) Error() string {\n\treturn fmt.Sprintf(\"%s: invalid %v (%s)\", e.Field, e.Value, e.Msg)\n}\n\nfunc Validate(v any) error {\n\treturn &ValidationError{Field: \"name\", Value: v, Msg: \"too short\"}\n}" },
		"Sentinel Errors": { exp: "Sentinel errors are predefined error variables (convention: names start with Err) used as sentinel values for specific failure conditions. Compare with == or use errors.Is.", code: "var ErrNotFound = errors.New(\"item not found\")\nvar ErrPermission = errors.New(\"permission denied\")\n\nfunc GetItem(id int) (Item, error) {\n\tif id < 0 {\n\t\treturn Item{}, ErrNotFound\n\t}\n\t// ...\n}\n\nitem, err := GetItem(-1)\nif errors.Is(err, ErrNotFound) {\n\tfmt.Println(\"handle not found\")\n}" },
		"Error Wrapping": { exp: "Use fmt.Errorf with %w to wrap errors, preserving the original error for errors.Is and errors.As. %W (uppercase) is NOT valid; use lowercase %w.", code: "func processFile(path string) error {\n\terr := openFile(path)\n\tif err != nil {\n\t\treturn fmt.Errorf(\"process %s: %w\", path, err)\n\t}\n\treturn nil\n}\n\n// Unwrap with errors.Is\nif errors.Is(err, os.ErrNotExist) {\n\tfmt.Println(\"file doesn't exist\")\n}" },
		"errors.Is and errors.As": { exp: "errors.Is(err, target) checks if any error in the chain matches target. errors.As(err, targetType) finds the first error of a given type. Both work through wrapping layers.", code: "// errors.Is: match sentinel errors\nif errors.Is(err, io.EOF) {\n\tfmt.Println(\"end of file\")\n}\n\n// errors.As: extract custom type\nvar valErr *ValidationError\nif errors.As(err, &valErr) {\n\tfmt.Printf(\"field %s invalid\\n\", valErr.Field)\n}" },
		"Panic & Recover": { exp: "Panic stops normal execution and unwinds the stack. Recover catches a panic inside a deferred function. Only use panics for truly exceptional, unrecoverable situations.", code: "defer func() {\n\tif r := recover(); r != nil {\n\t\tfmt.Println(\"Recovered:\", r)\n\t}\n}()\npanic(\"Something went wrong\")\n// Code after panic never runs" }
	},
	"Concurrency": {
		"Goroutines": { exp: "Lightweight concurrent execution managed by the Go runtime (not OS threads). Launch with go keyword. Goroutines share the same address space; use channels or sync primitives for coordination.", code: "go func() {\n\tfmt.Println(\"Running concurrently\")\n}()\nfmt.Println(\"Main continues\")\ntime.Sleep(time.Second)" },
		"Channels": { exp: "Typed conduits for goroutine communication. Use ch := make(chan T) to create. Send: ch <- v. Receive: v := <-ch. Block until both ends are ready.", code: "ch := make(chan int)\ngo func() { ch <- 42 }()\nvalue := <-ch // blocks until value sent\nfmt.Println(value) // 42" },
		"Buffered Channels": { exp: "Channels with capacity: make(chan T, cap). Send blocks only when buffer is full; receive blocks only when buffer is empty. Reduces synchronization points.", code: "ch := make(chan int, 2)\nch <- 1\nch <- 2\n// Non-blocking sends until buffer full\nfmt.Println(<-ch) // 1\nfmt.Println(<-ch) // 2" },
		"Range & Close": { exp: "Sender closes a channel with close(ch). Receiver can range over the channel, receiving values until the channel is closed. Detect closed channels with v, ok := <-ch.", code: "ch := make(chan int)\ngo func() {\n\tfor i := 0; i < 3; i++ {\n\t\tch <- i\n\t}\n\tclose(ch) // sender closes\n}()\n\nfor v := range ch {\n\tfmt.Println(v) // 0, 1, 2\n}" },
		"Select Statement": { exp: "Wait on multiple channel operations simultaneously. Select blocks until one case is ready. Use default for non-blocking operations. Use nil channels to disable cases.", code: "select {\ncase msg := <-ch1:\n\tfmt.Println(msg)\ncase msg := <-ch2:\n\tfmt.Println(msg)\ncase <-time.After(1 * time.Second):\n\tfmt.Println(\"timeout\")\ndefault:\n\tfmt.Println(\"no message ready\")\n}" },
		"WaitGroup": { exp: "sync.WaitGroup blocks until all goroutines finish. Add(n) increments the counter, Done() decrements, Wait() blocks until counter reaches 0. Typically Add is called before starting goroutines.", code: "var wg sync.WaitGroup\nfor i := 0; i < 5; i++ {\n\twg.Add(1)\n\tgo func(id int) {\n\t\tdefer wg.Done()\n\t\tfmt.Println(\"worker\", id)\n\t}(i)\n}\nwg.Wait()\nfmt.Println(\"all done\")" },
		"sync.Once": { exp: "sync.Once ensures a function is executed exactly once, even across multiple goroutines. Used for lazy initialization, singleton setup, and one-time configuration.", code: "var once sync.Once\nvar config *Config\n\nfunc GetConfig() *Config {\n\tonce.Do(func() {\n\t\tfmt.Println(\"initializing config...\")\n\t\tconfig = &Config{Port: 8080}\n\t})\n\treturn config\n}" },
		"Mutex & RWMutex": { exp: "sync.Mutex provides mutual exclusion. Lock/Unlock protects critical sections. sync.RWMutex allows multiple readers or one writer. RLock/RUnlock for read-only access.", code: "var mu sync.RWMutex\ndata := make(map[string]string)\n\nfunc Read(key string) string {\n\tmu.RLock()\n\tdefer mu.RUnlock()\n\treturn data[key]\n}\n\nfunc Write(key, val string) {\n\tmu.Lock()\n\tdefer mu.Unlock()\n\tdata[key] = val\n}" },
		"Worker Pools": { exp: "Fixed number of goroutines processing jobs from a channel. Controls concurrency, limits resource usage. Use a buffered channel for jobs and close it to signal completion.", code: "jobs := make(chan int, 100)\nresults := make(chan int, 100)\n\n// Start 3 workers\nfor w := 0; w < 3; w++ {\n\tgo func(id int) {\n\t\tfor j := range jobs {\n\t\t\tresults <- j * 2\n\t\t}\n\t}(w)\n}\n\n// Send jobs\nfor j := 0; j < 9; j++ {\n\tjobs <- j\n}\nclose(jobs)\n\n// Collect results\nfor r := 0; r < 9; r++ {\n\tfmt.Println(<-results)\n}" },
		"Fan-in / Fan-out": { exp: "Fan-out: multiple goroutines read from one channel (distributes work). Fan-in: multiple goroutines write to one channel (multiplexing results). Use a merge function with sync.WaitGroup.", code: "// Fan-in: merge multiple channels into one\nfunc merge(cs ...<-chan int) <-chan int {\n\tout := make(chan int)\n\tvar wg sync.WaitGroup\n\tfor _, c := range cs {\n\t\twg.Add(1)\n\t\tgo func(ch <-chan int) {\n\t\t\tdefer wg.Done()\n\t\t\tfor v := range ch {\n\t\t\t\tout <- v\n\t\t\t}\n\t\t}(c)\n\t}\n\tgo func() {\n\t\twg.Wait()\n\t\tclose(out)\n\t}()\n\treturn out\n}" }
	},
	"Packages & Imports": {
		"Package Declaration": { exp: "Every Go file belongs to a package. Executables use 'package main', libraries use any descriptive name. One directory = one package.", code: "// File: main.go\npackage main\n\n// Library packages\npackage mylib\npackage httpclient" },
		"Importing Packages": { exp: "Use import for dependencies. Standard library packages have short paths; remote packages use full module paths. go mod tidy manages required versions.", code: "import \"fmt\"\nimport (\n\t\"strings\"\n\t\"github.com/user/pkg\"\n)" },
		"Exported Names": { exp: "Capitalized names are exported (public), lowercase are unexported (package-private). Exported names are accessible across packages; unexported only within the same package.", code: "type User struct{}      // Exported\ntype user struct{}      // Unexported\nfunc Public() {}          // Exported\nfunc private() {}         // Unexported\nconst MaxValue = 100      // Exported\nconst minValue = 1        // Unexported" },
		"Package Initialization (init)": { exp: "init() runs when a package is imported. Multiple init()s across a package run in file name order. init() functions cannot be called directly. They run before main().", code: "var schema = \"public\"\n\nfunc init() {\n\tif os.Getenv(\"DB_SCHEMA\") != \"\" {\n\t\tschema = os.Getenv(\"DB_SCHEMA\")\n\t}\n}\n\n// Init order: imported packages first (bottom-up), then package-level vars, then init()s, then main()" },
		"Internal Packages": { exp: "Packages under an 'internal/' directory are only importable by code rooted at the internal's parent. Enforces encapsulation boundaries within a module.", code: "project/\n\u2514\u2500\u2500 internal/\n    \u2514\u2500\u2500 auth/\n        \u2514\u2500\u2500 token.go  // only importable by project/...\n\npackage internal/auth\n// This can ONLY be imported by code inside project/" },
		"Blank Imports": { exp: "Import a package solely for its side effects (init() execution) using _. The dot alias '.' imports all exported names into the current namespace.", code: "import (\n\t_ \"net/http/pprof\" // registers pprof handlers via init()\n\t. \"fmt\"           // use Println directly (rare, avoid)\n\t_ \"image/png\"     // registers PNG decoder\n)\n\n// Blank import for side effects only" },
		"Import Cycles": { exp: "Go does not allow import cycles. A cannot import B if B imports A (directly or indirectly). Break cycles by extracting shared types into a third package, or using interfaces.", code: "// BAD: import cycle\n// package a imports b\n// package b imports a\n\n// FIX: extract shared types\n// package a imports c\n// package b imports c\n// package c (no imports)" }
	},
	"File I/O": {
		"Reading Files (os.ReadFile)": { exp: "os.ReadFile (Go 1.16+) reads a file into memory. Replaces deprecated ioutil.ReadFile. Use for small files. For large files, use bufio.Scanner or io.Copy with limited buffer.", code: "data, err := os.ReadFile(\"file.txt\")\nif err != nil {\n\tlog.Fatal(err)\n}\nfmt.Println(string(data))" },
		"Writing Files (os.WriteFile)": { exp: "os.WriteFile writes data to a file, creating or truncating it. The third argument is file permissions (Unix mode). Replaces deprecated ioutil.WriteFile.", code: "content := []byte(\"Hello, Go!\")\nerr := os.WriteFile(\"output.txt\", content, 0644)\nif err != nil {\n\tlog.Fatal(err)\n}" },
		"Buffered I/O (bufio)": { exp: "bufio provides buffered reading and writing for efficiency. bufio.Scanner reads line-by-line (default) or via SplitFunc. bufio.Writer buffers writes to reduce syscalls.", code: "file, err := os.Open(\"data.txt\")\nif err != nil { log.Fatal(err) }\ndefer file.Close()\n\nscanner := bufio.NewScanner(file)\nfor scanner.Scan() {\n\tfmt.Println(scanner.Text())\n}\nif err := scanner.Err(); err != nil {\n\tlog.Fatal(err)\n}" },
		"io.ReadAll": { exp: "io.ReadAll reads from an io.Reader until EOF, returning the full byte slice. Replaces ioutil.ReadAll. Works with any reader: files, HTTP bodies, strings, etc.", code: "r := strings.NewReader(\"hello world\")\ndata, err := io.ReadAll(r)\nif err != nil {\n\tlog.Fatal(err)\n}\nfmt.Println(string(data)) // \"hello world\"" },
		"io.Copy": { exp: "io.Copy copies from an io.Reader to an io.Writer until EOF. Efficiently streams data without loading everything into memory. Returns bytes copied and any error.", code: "src, _ := os.Open(\"source.txt\")\ndefer src.Close()\ndst, _ := os.Create(\"dest.txt\")\ndefer dst.Close()\n\nwritten, err := io.Copy(dst, src)\nfmt.Printf(\"copied %d bytes\\n\", written)" },
		"File Permissions & ioutil Deprecation": { exp: "ioutil is deprecated since Go 1.16. Replace ioutil.ReadFile with os.ReadFile, ioutil.WriteFile with os.WriteFile, ioutil.ReadAll with io.ReadAll, ioutil.TempFile with os.CreateTemp.", code: "// Old (deprecated)\n// data, _ := ioutil.ReadFile(\"f.txt\")\n// ioutil.WriteFile(\"f.txt\", data, 0644)\n// ioutil.ReadAll(r)\n\n// New (Go 1.16+)\ndata, _ := os.ReadFile(\"f.txt\")\nos.WriteFile(\"f.txt\", data, 0644)\nio.ReadAll(r)" },
		"Directory Operations": { exp: "Read directories with os.ReadDir (returns sorted []os.DirEntry). Walk directory trees with filepath.Walk or filepath.WalkDir. Create dirs with os.MkdirAll.", code: "entries, err := os.ReadDir(\".\")\nfor _, e := range entries {\n\tfmt.Println(e.Name(), e.IsDir())\n}\n\n// Walk directory tree\nfilepath.WalkDir(\".\", func(path string, d fs.DirEntry, err error) error {\n\tfmt.Println(path)\n\treturn nil\n})" }
	},
	"Testing": {
		"Test Functions": { exp: "Write tests in *_test.go files. Test functions follow func TestXxx(t *testing.T). Use t.Error/t.Fatal for failures. Run with go test.", code: "func TestAdd(t *testing.T) {\n\tresult := Add(2, 3)\n\tif result != 5 {\n\t\tt.Errorf(\"Expected 5, got %d\", result)\n\t}\n}\n\n// go test .\n// go test -v .  (verbose)" },
		"Table-Driven Tests": { exp: "Define test cases as a slice of structs. Iterate over them for clean, DRY tests that cover many inputs. Each case can include a name for clear failure output.", code: "cases := []struct {\n\tname string\n\ta, b int\n\twant int\n}{\n\t{\"positive\", 2, 3, 6},\n\t{\"zero\", 0, 5, 0},\n\t{\"negative\", -2, 3, -6},\n}\nfor _, tc := range cases {\n\tgot := Multiply(tc.a, tc.b)\n\tif got != tc.want {\n\t\tt.Errorf(\"%s: got %d, want %d\", tc.name, got, tc.want)\n\t}\n}" },
		"Subtests": { exp: "Run subtests with t.Run(name, fn) for hierarchical test organization. Subtests share setup/teardown and can be run selectively with go test -run pattern.", code: "func TestMath(t *testing.T) {\n\tt.Run(\"add\", func(t *testing.T) {\n\t\tif Add(1, 2) != 3 {\n\t\t\tt.Fatal(\"wrong\")\n\t\t}\n\t})\n\tt.Run(\"multiply\", func(t *testing.T) {\n\t\tif Multiply(2, 3) != 6 {\n\t\t\tt.Fatal(\"wrong\")\n\t\t}\n\t})\n}\n// go test -run \"TestMath/add\"  (selective)" },
		"Test Helpers": { exp: "Helper functions in tests reduce boilerplate. Call t.Helper() to mark a function as a test helper so failure line numbers point to the caller, not the helper.", code: "func setupDB(t *testing.T) *sql.DB {\n\tt.Helper()\n\tdb, err := sql.Open(\"sqlite3\", \":memory:\")\n\tif err != nil {\n\t\tt.Fatalf(\"setup failed: %v\", err)\n\t}\n\treturn db\n}\n\nfunc TestQuery(t *testing.T) {\n\tdb := setupDB(t) // failure points here, not inside setupDB\n\tdefer db.Close()\n\t// ...\n}" },
		"Test Coverage": { exp: "Go has built-in coverage. Run go test -cover to see percentage. go test -coverprofile=coverage.out generates a profile. Use go tool cover -html=coverage.out for visual report.", code: "# Run with coverage\n$ go test -cover ./...\n# Output: ok  myapp/mypkg  0.002s  coverage: 85.2% of statements\n\n# Generate HTML report\ngo test -coverprofile=coverage.out ./...\ngo tool cover -html=coverage.out -o coverage.html" },
		"Fuzzing": { exp: "Go 1.18+ fuzzing randomly generates inputs to find bugs. Fuzz test: func FuzzXxx(f *testing.F). Seed with f.Add(), then f.Fuzz(targetFn).", code: "func FuzzReverse(f *testing.F) {\n\t// Seed corpus\n\tf.Add(\"hello\")\n\tf.Add(\"世界\")\n\n\tf.Fuzz(func(t *testing.T, s string) {\n\t\trev := Reverse(s)\n\t\tdouble := Reverse(rev)\n\t\tif s != double {\n\t\t\tt.Errorf(\"round-trip: %q -> %q -> %q\", s, rev, double)\n\t\t}\n\t})\n}\n// go test -fuzz=FuzzReverse" },
		"Benchmarks": { exp: "Measure performance with BenchmarkXxx(b *testing.B). b.N is adjusted by the framework for stable timing. Use b.ResetTimer() and b.ReportAllocs() for accurate measurements.", code: "func BenchmarkAdd(b *testing.B) {\n\tfor i := 0; i < b.N; i++ {\n\t\tAdd(2, 3)\n\t}\n}\n\nfunc BenchmarkComplex(b *testing.B) {\n\tdata := prepareData()\n\tb.ResetTimer() // exclude setup time\n\tb.ReportAllocs() // report allocation stats\n\tfor i := 0; i < b.N; i++ {\n\t\tprocess(data)\n\t}\n}\n// go test -bench=. -benchmem" }
	},
	"Standard Library": {
		"fmt Package": { exp: "Formatted I/O with Print, Printf, Println, Sprintf, Fprintf. Verbs: %v (value), %+v (with fields), %T (type), %d (int), %s (string), %#v (Go-syntax).", code: "fmt.Println(\"Hello\")\nfmt.Printf(\"Value: %d, Type: %T\\n\", 42, 42)\ns := fmt.Sprintf(\"hex: %x\", 255) // \"ff\"\nfmt.Fprintf(os.Stderr, \"error: %v\\n\", err)" },
		"strings & strconv Packages": { exp: "strings: Contains, Split, Join, ToUpper, ToLower, Trim, Replace, Builder (efficient string building). strconv: Atoi, Itoa, ParseBool, FormatFloat, ParseInt.", code: "s := \"hello world\"\nfmt.Println(strings.ToUpper(s))\nparts := strings.Split(s, \" \")\n\nn, _ := strconv.Atoi(\"42\")\ns2 := strconv.Itoa(42)\n\nvar b strings.Builder\nfor i := 0; i < 100; i++ {\n\tb.WriteString(\"a\")\n}\nfmt.Println(b.String())" },
		"io Package": { exp: "Core I/O interfaces: io.Reader, io.Writer, io.Closer, io.Seeker. Utility functions: io.Copy, io.ReadAll, io.MultiReader, io.TeeReader, io.LimitReader.", code: "var w io.Writer = os.Stdout\nfmt.Fprint(w, \"output\")\n\n// MultiReader chains readers\nr := io.MultiReader(strings.NewReader(\"a\"), strings.NewReader(\"b\"))\n\n// TeeReader mirrors reads to a writer\npr, pw := io.Pipe()\nio.Copy(os.Stdout, pr) // reads from pr" },
		"encoding/json Package": { exp: "Marshal/Unmarshal Go values to/from JSON. Struct tags control field names, omitempty skips zero values. Use json.NewDecoder for streaming JSON (files, HTTP).", code: "type Person struct {\n\tName string `json:\"name\"`\n\tAge  int    `json:\"age,omitempty\"`\n}\n\n// Marshal\nb, _ := json.Marshal(Person{\"Alice\", 30})\nfmt.Println(string(b)) // {\"name\":\"Alice\",\"age\":30}\n\n// Unmarshal\nvar p Person\njson.Unmarshal(b, &p)\n\n// Streaming\njson.NewDecoder(r).Decode(&p)" },
		"flag Package": { exp: "Parse command-line flags with flag package. Supports -flag, -flag=x, --flag (double dash works). Types: String, Int, Bool, Duration, Float64, or custom flag.Value.", code: "var port = flag.Int(\"port\", 8080, \"port to listen on\")\nvar name = flag.String(\"name\", \"world\", \"greeting name\")\nvar verbose = flag.Bool(\"v\", false, \"verbose output\")\nflag.Parse()\n\nfmt.Printf(\"port=%d\\n\", *port)\n\n// Usage: ./app -port=9090 -name=Alice -v" },
		"log Package": { exp: "Simple logging to stderr with timestamps. log.Printf, log.Fatalf (calls os.Exit(1)), log.Panicf (calls panic). Use log.New for custom output, flags, and prefix.", code: "log.Println(\"starting server...\")\nlog.Printf(\"port=%d\", 8080)\n// log.Fatalf(\"fatal: %v\", err) // exits\n\n// Custom logger\nl := log.New(os.Stderr, \"MYAPP: \", log.Ldate|log.Ltime|log.Lshortfile)\nl.Println(\"custom formatted log\")" },
		"os/exec Package": { exp: "Run external commands. exec.Command(name, args...). cmd.Output() returns stdout, cmd.CombinedOutput() returns both. Pipe stdin/stdout/stderr for interactive commands.", code: "cmd := exec.Command(\"ls\", \"-la\")\nout, err := cmd.Output()\nif err != nil {\n\tlog.Fatal(err)\n}\nfmt.Println(string(out))\n\n// With pipes\ncmd.Stdin = strings.NewReader(\"input data\")\ncmd.Stdout = os.Stdout\ncmd.Stderr = os.Stderr\ncmd.Run()" },
		"time Package": { exp: "Time and duration with nanosecond precision. Parse (reference time: Mon Jan 2 15:04:05 MST 2006 = 1 2 3 4 5 6 -7). Timer/Ticker for events. Sleep for pauses.", code: "now := time.Now()\nfuture := now.Add(24 * time.Hour)\nfmt.Println(now.Format(\"2006-01-02\"))\n\nparsed, _ := time.Parse(\"2006-01-02\", \"2026-05-13\")\n\n// Ticker\nticker := time.NewTicker(time.Second)\ngo func() {\n\tfor range ticker.C {\n\t\tfmt.Println(\"tick\")\n\t}\n}()" },
		"context Package": { exp: "Context propagates deadlines, cancellation signals, and request-scoped values. Create with context.Background() or context.TODO(). Derive with WithCancel, WithTimeout, WithDeadline, WithValue.", code: "ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)\ndefer cancel()\n\ngo func(ctx context.Context) {\n\tselect {\n\tcase <-ctx.Done():\n\t\tfmt.Println(\"cancelled:\", ctx.Err())\n\tcase result := <-doWork():\n\t\tfmt.Println(result)\n\t}\n}(ctx)" },
		"sync Package": { exp: "Synchronization primitives: Mutex, RWMutex, WaitGroup, Once, Cond, Pool, Map (concurrent-safe map). sync.Map is optimized for read-heavy or append-only patterns.", code: "var mu sync.Mutex\nvar counter int\n\nvar wg sync.WaitGroup\nfor i := 0; i < 10; i++ {\n\twg.Add(1)\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tmu.Lock()\n\t\tcounter++\n\t\tmu.Unlock()\n\t}()\n}\nwg.Wait()\nfmt.Println(\"Counter:\", counter)" }
	},
	"Modules & Tooling": {
		"Go Modules": { exp: "Go modules define a project's dependencies and versioning. go.mod declares the module path and requirements. go.sum contains checksums for reproducibility.", code: "go mod init github.com/user/myapp\ngo get github.com/gorilla/mux@v1.8.0\ngo mod tidy   # cleans go.mod and go.sum\ngo mod vendor # copies deps to vendor/\ngo mod verify # verifies checksums" },
		"Workspace Mode": { exp: "Go 1.18+ workspace mode (go.work) lets you work on multiple modules simultaneously. Useful for local development across interdependent modules. go work init creates the file.", code: "go.work file:\ngo 1.22\n\nuse (\n\t./myapp\n\t./sharedlib\n\t./tools\n)\n\n# Commands\n$ go work init ./myapp ./sharedlib\n$ go work use ./newmod\n$ go work sync" },
		"Build Tags": { exp: "Build tags (or build constraints) conditionally compile files. Placed at top of file: //go:build tag. Multiple tags combine with &&, ||, and !. Use for platform-specific code or feature flags.", code: "//go:build linux\n\npackage main\nfunc getOS() string { return \"Linux\" }\n\n//go:build !linux\n\npackage main\nfunc getOS() string { return \"non-Linux\" }\n\n// Build: go build -tags \"debug\"\n//go:build debug\nvar DebugMode = true" },
		"go generate": { exp: "go generate scans //go:generate directives to run tools automatically. Commonly used for code generation: protobufs, stringers, mocks, and embed. Run with go generate ./....", code: "//go:generate stringer -type=Pill\n//go:generate protoc --go_out=. proto/*.proto\n//go:generate mockgen -source=interface.go -destination=mocks.go\n\ntype Pill int\n\nconst (\n\tAspirin Pill = iota\n\tIbuprofen\n\tAcetaminophen\n)\n\n// Run: go generate ./..." },
		"go tooling (vet, fmt, fix)": { exp: "go vet detects suspicious constructs (e.g., unreachable code, wrong Printf verbs). go fmt automatically formats code to canonical style. go fix updates old API usage to newer versions.", code: "go vet ./...      # static analysis\n# Detects: unreachable code, wrong Printf args, etc.\n\ngo fmt ./...      # formats all files\n# Equivalent to: gofmt -l -w .\n\ngo fix ./...      # migrate deprecated APIs\ngo tool pprof     # CPU/memory profiling\ngo tool trace     # execution trace" },
		"Dependency Management (go get)": { exp: "go get manages module dependencies. Latest compatible version: go get pkg@latest. Specific version: go get pkg@v1.2.3. Upgrade minor: go get -u ./.... Remove unused: go mod tidy.", code: "go get github.com/gorilla/mux@latest\n# upgrades to latest tagged version\n\ngo get github.com/gorilla/mux@v1.8.0\n# specific version\n\ngo get -u ./...\n# upgrade all direct/indirect deps\n\ngo mod tidy\n# removes unused deps, adds missing" },
		"Generics": { exp: "Go 1.18+ supports type parameters for functions and types. Use constraints (interface with type sets) to restrict acceptable types. 'any' is a shortcut for interface{}. Comparable constraint for ==.", code: "func Map[T any, U any](input []T, fn func(T) U) []U {\n\tresult := make([]U, len(input))\n\tfor i, v := range input {\n\t\tresult[i] = fn(v)\n\t}\n\treturn result\n}\n\n// Generic type with constraint\ntype Stack[T comparable] struct {\n\titems []T\n}\nfunc (s *Stack[T]) Push(v T) {\n\ts.items = append(s.items, v)\n}\n\nnums := []int{1, 2, 3}\ndoubled := Map(nums, func(n int) int { return n * 2 })\nfmt.Println(doubled)" }
	},
	"Networking": {
		"HTTP Server (net/http)": { exp: "Build HTTP servers with http.HandleFunc or http.Handler interface. http.ListenAndServe starts the server. Default mux is http.DefaultServeMux.", code: "http.HandleFunc(\"/hello\", func(w http.ResponseWriter, r *http.Request) {\n\tfmt.Fprintf(w, \"Hello, %s!\", r.URL.Query().Get(\"name\"))\n})\nhttp.HandleFunc(\"/api/data\", func(w http.ResponseWriter, r *http.Request) {\n\tw.Header().Set(\"Content-Type\", \"application/json\")\n\tjson.NewEncoder(w).Encode(map[string]string{\"key\": \"value\"})\n})\nlog.Fatal(http.ListenAndServe(\":8080\", nil))" },
		"HTTP Client": { exp: "http.Client with Get, Post, Do methods. Respect context cancellation, always close response body, set timeouts to avoid hanging connections.", code: "client := &http.Client{\n\tTimeout: 10 * time.Second,\n}\n\nresp, err := client.Get(\"https://api.example.com/data\")\nif err != nil {\n\tlog.Fatal(err)\n}\ndefer resp.Body.Close()\n\nbody, err := io.ReadAll(resp.Body)\nif err != nil {\n\tlog.Fatal(err)\n}\nfmt.Println(string(body))" },
		"Routing & ServeMux (Go 1.22+)": { exp: "Go 1.22 enhanced the default mux with method-based routing and path parameters using {param} and {param...} patterns.", code: "mux := http.NewServeMux()\nmux.HandleFunc(\"GET /users/{id}\", func(w http.ResponseWriter, r *http.Request) {\n\tid := r.PathValue(\"id\")\n\tfmt.Fprintf(w, \"user %s\", id)\n})\nmux.HandleFunc(\"POST /users\", createUser)\n\n// Wildcard\nmux.HandleFunc(\"/static/{path...}\", serveStatic)\n\nlog.Fatal(http.ListenAndServe(\":8080\", mux))" },
		"Middleware Pattern": { exp: "Middleware wraps http.Handler to add cross-cutting concerns: logging, auth, recovery, rate limiting, CORS. Use a function that takes and returns http.Handler.", code: "func Logger(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tstart := time.Now()\n\t\tnext.ServeHTTP(w, r)\n\t\tlog.Printf(\"%s %s %s\", r.Method, r.URL.Path, time.Since(start))\n\t})\n}\n\nfunc Recovery(next http.Handler) http.Handler {\n\treturn http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\t\tdefer func() {\n\t\t\tif err := recover(); err != nil {\n\t\t\t\thttp.Error(w, \"Internal Error\", 500)\n\t\t\t}\n\t\t}()\n\t\tnext.ServeHTTP(w, r)\n\t})\n}\n\n// Chain\nhttp.ListenAndServe(\":8080\", Logger(Recovery(mux)))" },
		"Templates (html/template)": { exp: "html/template generates safe HTML output with automatic context-aware escaping. Use template.ParseFiles or template.New(). Execute with a data struct and func map.", code: "// Template file: index.html\n// <h1>{{.Title}}</h1>\n// <ul>{{range .Items}}<li>{{.}}</li>{{end}}</ul>\n\ntmpl := template.Must(template.ParseFiles(\"index.html\"))\ndata := struct {\n\tTitle string\n\tItems []string\n}{\n\tTitle: \"Go Page\",\n\tItems: []string{\"A\", \"B\", \"C\"},\n}\n\nhttp.HandleFunc(\"/\", func(w http.ResponseWriter, r *http.Request) {\n\ttmpl.Execute(w, data)\n})" },
		"TLS & HTTPS": { exp: "Use http.ListenAndServeTLS to serve HTTPS. Generate self-signed certs with crypto/tls or use Let's Encrypt via autocert. Always serve HTTPS in production.", code: "// Generate cert: go run crypto/tls/generate_cert.go --host localhost\n\nmux := http.NewServeMux()\nmux.HandleFunc(\"/\", func(w http.ResponseWriter, r *http.Request) {\n\tfmt.Fprintf(w, \"Secure connection!\")\n})\n\nlog.Fatal(http.ListenAndServeTLS(\":443\", \"cert.pem\", \"key.pem\", mux))\n\n// HTTP to HTTPS redirect\nhttp.ListenAndServe(\":80\", http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n\thttp.Redirect(w, r, \"https://\"+r.Host+r.URL.String(), 301)\n}))" },
		"TCP & UDP Sockets": { exp: "Low-level networking with net.Dial (TCP/UDP) and net.Listen. Build custom protocols. Use bufio for line-based protocols. Always set deadlines.", code: "// TCP echo server\nln, err := net.Listen(\"tcp\", \":8080\")\nif err != nil { log.Fatal(err) }\ndefer ln.Close()\n\nfor {\n\tconn, err := ln.Accept()\n\tif err != nil { continue }\n\tgo func(c net.Conn) {\n\t\tdefer c.Close()\n\t\tio.Copy(c, c) // echo back\n\t}(conn)\n}" }
	},
	"Database & SQL": {
		"database/sql Interface": { exp: "database/sql provides a generic SQL interface. Open a database with sql.Open (driver name + DSN). Use sql.DB for connection pooling. Run queries with Query, QueryRow, Exec.", code: "db, err := sql.Open(\"postgres\", \"host=localhost port=5432 user=app dbname=app sslmode=disable\")\nif err != nil {\n\tlog.Fatal(err)\n}\ndefer db.Close()\n\n// Ping to verify connection\nif err := db.Ping(); err != nil {\n\tlog.Fatal(err)\n}" },
		"Querying (Query & QueryRow)": { exp: "Query returns *sql.Rows (cursor). Iterate with rows.Next() and rows.Scan(). QueryRow returns at most one row, returns sql.ErrNoRows if none. Always close rows.", code: "// Query multiple rows\nrows, err := db.Query(\"SELECT id, name FROM users WHERE active = $1\", true)\nif err != nil { log.Fatal(err) }\ndefer rows.Close()\n\nfor rows.Next() {\n\tvar id int\n\tvar name string\n\tif err := rows.Scan(&id, &name); err != nil {\n\t\tlog.Fatal(err)\n\t}\n\tfmt.Println(id, name)\n}\nif err := rows.Err(); err != nil {\n\tlog.Fatal(err)\n}\n\n// Single row\nvar count int\nerr = db.QueryRow(\"SELECT COUNT(*) FROM users\").Scan(&count)" },
		"Prepared Statements": { exp: "Prepare statements with db.Prepare for repeated execution. Prevents SQL injection and improves performance. Use $1, $2 (PostgreSQL) or ? (MySQL/SQLite) placeholders.", code: "stmt, err := db.Prepare(\"INSERT INTO users(name, email) VALUES($1, $2)\")\nif err != nil { log.Fatal(err) }\ndefer stmt.Close()\n\n// Reuse\nstmt.Exec(\"Alice\", \"alice@example.com\")\nstmt.Exec(\"Bob\", \"bob@example.com\")\n\n// Or use Exec with args directly (implicit prepare)\ndb.Exec(\"INSERT INTO users(name) VALUES($1)\", name)" },
		"Transactions": { exp: "Use db.Begin() to start a transaction. tx.Exec, tx.Query within the transaction. Commit or Rollback. Ensures atomicity — all operations succeed or none do.", code: "tx, err := db.Begin()\nif err != nil { log.Fatal(err) }\ndefer tx.Rollback() // no-op if committed\n\n_, err = tx.Exec(\"UPDATE accounts SET balance = balance - $1 WHERE id = $2\", 100, 1)\nif err != nil { return err }\n\n_, err = tx.Exec(\"UPDATE accounts SET balance = balance + $1 WHERE id = $2\", 100, 2)\nif err != nil { return err }\n\nif err := tx.Commit(); err != nil {\n\tlog.Fatal(err)\n}" },
		"Connection Pooling": { exp: "sql.DB manages a connection pool. Configure with SetMaxOpenConns (max concurrent), SetMaxIdleConns (idle pool), SetConnMaxLifetime (connection age), SetConnMaxIdleTime.", code: "db, _ := sql.Open(\"postgres\", dsn)\n\n// Tune the pool\ndb.SetMaxOpenConns(25)   // max simultaneous connections\ndb.SetMaxIdleConns(5)    // keep 5 idle\ndb.SetConnMaxLifetime(5 * time.Minute)  // recycle connections\ndb.SetConnMaxIdleTime(1 * time.Minute)   // close idle connections\n\n// Ping checks a connection from the pool\nctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)\ndefer cancel()\ndb.PingContext(ctx)" },
		"Migrations (golang-migrate)": { exp: "Manage schema changes with migration tools like golang-migrate/migrate. Migration files: 001_create_users.up.sql and 001_create_users.down.sql. Run up/down programmatically via CLI.", code: "// Install: go install -tags 'postgres' github.com/golang-migrate/migrate/v4/cmd/migrate@latest\n\n// Migration file: 001_create_users.up.sql\n// CREATE TABLE users (\n//     id SERIAL PRIMARY KEY,\n//     name VARCHAR(255) NOT NULL\n// );\n\n// Rollback: 001_create_users.down.sql\n// DROP TABLE IF EXISTS users;\n\n// Programmatic\nimport \"github.com/golang-migrate/migrate/v4\"\n\nm, err := migrate.New(\"file://migrations\", \"postgres://...\")\nm.Up()    // apply all up migrations\nm.Steps(2) // apply 2 migrations\nm.Down()   // rollback all" },
		"Database Drivers": { exp: "Register database drivers via blank imports. Common drivers: lib/pq (PostgreSQL), go-sql-driver/mysql (MySQL), mattn/go-sqlite3 (SQLite), mongo-driver (MongoDB).", code: "import (\n\t_ \"github.com/lib/pq\"         // PostgreSQL driver\n\t_ \"github.com/go-sql-driver/mysql\" // MySQL driver\n\t_ \"github.com/mattn/go-sqlite3\"    // SQLite driver\n)\n\n// Opens PostgreSQL\ndb, _ := sql.Open(\"postgres\", dsn)\n// Opens MySQL\ndb, _ := sql.Open(\"mysql\", \"user:pass@tcp(host:3306)/db\")\n// Opens SQLite\ndb, _ := sql.Open(\"sqlite3\", \"./data.db\")" }
	},
	"Learning Go & Best Practices": {
		"Go Design Philosophy": { exp: "Learning Go emphasizes simplicity: no inheritance, no generics (until 1.18), no exceptions. Go favors composition over inheritance, explicit error handling, and readability over cleverness. Bodner calls this 'the boring language that gets things done'. The key insight: Go is designed for large teams maintaining code over years.", code: "// Composition over inheritance\ntype Reader interface { Read([]byte) (int, error) }\ntype Writer interface { Write([]byte) (int, error) }\n\n// Embedding promotes methods\ntype ReadWriter struct {\n\tReader\n\tWriter\n}\n\n// Explicit error handling (not exceptions)\nresult, err := doWork()\nif err != nil {\n\treturn fmt.Errorf(\"doWork: %w\", err)\n}" },
		"nil & Zero Values Mental Model": { exp: "Know Go teaches the nil mental model: nil is a value, not an error. Nil slices have len=0 and can append to. Nil maps return zero values but panic on write. Nil interfaces have dynamic type nil (not just value nil). A nil pointer inside an interface makes it non-nil! Book insight: always think about what zero value means for your types.", code: "var s []int           // nil slice, len=0, append works\ns = append(s, 1)      // OK: makes new slice\nvar m map[string]int   // nil map, read returns zero\n_ = m[\"key\"]           // OK: returns 0\n// m[\"key\"] = 1       // PANIC: write to nil map\n\n// Nil interface trap\nvar buf *bytes.Buffer = nil\nvar w io.Writer = buf    // interface NOT nil (has type *bytes.Buffer)\nif w != nil { w.Write([]byte(\"hi\")) } // PANIC: nil deref\n\n// Zero value convention\ntype Counter struct{ n int } // zero value is ready to use\nfunc (c *Counter) Inc() { c.n++ }" },
		"slog Structured Logging (Go 1.21+)": { exp: "slog provides structured, leveled logging with key-value pairs. Levels: Debug, Info, Warn, Error. Use slog.New with JSONHandler or TextHandler. slog.Group for nested keys. slog.Attr for reusable attributes. The book recommendation: always use structured logging for production.", code: "import \"log/slog\"\n\n// Default logger (text)\nslog.Info(\"server starting\", \"port\", 8080, \"env\", \"production\")\n\n// JSON logger\nlogger := slog.New(slog.NewJSONHandler(os.Stderr, &slog.HandlerOptions{\n\tLevel: slog.LevelDebug,\n\tAddSource: true,\n}))\nlogger.Debug(\"debug message\", \"key\", \"value\")\nlogger.Warn(\"rate limit\", \"ip\", \"10.0.0.1\", \"count\", 42)\nlogger.Error(\"db conn failed\", \"db\", \"users\", slog.Int(\"retry\", 3))\n\n// With: add context to all subsequent logs\nlogger = logger.With(\"service\", \"api\", \"version\", \"2.0\")\nlogger.Info(\"request\", \"path\", \"/users\")\n\n// Group\nslog.Info(\"request\", slog.Group(\"http\",\n\tslog.String(\"method\", \"GET\"),\n\tslog.Int(\"status\", 200),\n))" },
		"errors.Join & Error Handling (Go 1.20+)": { exp: "errors.Join combines multiple errors into one. Useful for batch validation and deferred cleanup. Know Go emphasizes thinking of errors as values that can be combined. Also new: fmt.Errorf with multiple %w (Go 1.20+ can wrap multiple errors).", code: "func validate(user User) error {\n\tvar errs error\n\tif user.Name == \"\" {\n\t\terrs = errors.Join(errs, errors.New(\"name required\"))\n\t}\n\tif user.Age < 0 {\n\t\terrs = errors.Join(errs, errors.New(\"invalid age\"))\n\t}\n\tif user.Email == \"\" {\n\t\terrs = errors.Join(errs, errors.New(\"email required\"))\n\t}\n\treturn errs\n}\n\n// Go 1.20+: wrap multiple errors (experimental)\n// return fmt.Errorf(\"validate: %w; %w\", err1, err2)\n\n// errors.Is works through Join\nerr := validate(User{})\nif errors.Is(err, errors.New(\"name required\")) {\n\tfmt.Println(\"handle name error\")\n}" },
		"maps & slices Packages (Go 1.21+)": { exp: "Standard library packages for generic operations on maps and slices. No more hand-rolling Contains, DeleteFunc, Filter, etc. These are type-safe and efficient.", code: "import (\n\t\"maps\"\n\t\"slices\"\n)\n\n// slices\nnames := []string{\"bob\", \"alice\", \"charlie\"}\nslices.Sort(names)                         // in-place sort\nslices.SortFunc(names, strings.Compare)    // custom comparator\nslices.Reverse(names)\nidx := slices.Index(names, \"bob\")          // find index\nfound := slices.Contains(names, \"alice\")    // contains check\nuniq := slices.Compact([]string{\"a\",\"a\",\"b\"}) // deduplicate adjacent\n\n// maps\nages := map[string]int{\"alice\": 30, \"bob\": 25}\nmaps.DeleteFunc(ages, func(k string, v int) bool { return v < 28 })\nkeys := maps.Keys(ages)    // slice of keys\nvals := maps.Values(ages)  // slice of values\nclone := maps.Clone(ages)" },
		"Range over Iterators & func (Go 1.23+)": { exp: "Go 1.23 adds range-over-iterator support. Any function with func(yield func(K, V) bool) can be ranged. The iter package provides Seq and Seq2 types. Libraries can expose iterators instead of requiring callbacks.", code: "package main\n\n// Backwards iterates over a slice in reverse\nfunc Backwards[E any](s []E) func(func(int, E) bool) {\n\treturn func(yield func(int, E) bool) {\n\t\tfor i := len(s) - 1; i >= 0; i-- {\n\t\t\tif !yield(i, s[i]) {\n\t\t\t\treturn\n\t\t\t}\n\t\t}\n\t}\n}\n\nfunc main() {\n\ts := []string{\"a\", \"b\", \"c\"}\n\tfor i, v := range Backwards(s) {\n\t\tfmt.Println(i, v)  // 2 c, 1 b, 0 a\n\t}\n}\n\n// Standard library iterator examples (Go 1.23+)\n// for k, v := range maps.All(m) { ... }" },
		"Embedding (//go:embed)": { exp: "go:embed embeds files into the binary at compile time. Supports files, directories, and globs. Embed as []byte, string, or embed.FS. Know Go recommends embed for static assets over reading files at runtime.", code: "import \"embed\"\n\n//go:embed static/index.html\nvar indexHTML string\n\n//go:embed static/*.css\nvar cssFiles embed.FS\n\n//go:embed config.toml\nvar configBytes []byte\n\nhttp.HandleFunc(\"/\", func(w http.ResponseWriter, r *http.Request) {\n\tfmt.Fprint(w, indexHTML)\n})\n\nhttp.Handle(\"/static/\", http.FileServer(http.FS(cssFiles)))\n\n// Use embedded config\nvar cfg Config\ntoml.Unmarshal(configBytes, &cfg)" },
		"Race Detector & Data Races": { exp: "The Go race detector catches concurrent unsafe access. Run with -race flag. Learning Go: if two goroutines access the same variable without synchronization, it's a race. Know Go says 'always run tests with -race before shipping'. The detector has ~false negative rate but no false positives.", code: "// Race example (detect with: go run -race .)\nvar counter int\nvar wg sync.WaitGroup\nfor i := 0; i < 1000; i++ {\n\twg.Add(1)\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tcounter++  // RACE: unsynchronized write\n\t}()\n}\nwg.Wait()\n\n// Fix: use atomic or mutex\nvar atomicCounter atomic.Int64\nfor i := 0; i < 1000; i++ {\n\twg.Add(1)\n\tgo func() {\n\t\tdefer wg.Done()\n\t\tatomicCounter.Add(1)  // safe\n\t}()\n}\n\n// Run: go test -race ./...\n// Run: go build -race ." },
		"Profiling & pprof": { exp: "Go's built-in profiler: CPU, memory, goroutine, mutex, block profiles. Learning Go: always profile before optimizing. Use net/http/pprof for web apps, runtime/pprof for CLIs. The book's advice: 'measure, don't guess'.", code: "import _ \"net/http/pprof\"\n\n// Web app: add pprof handlers\nhttp.HandleFunc(\"/debug/pprof/\", http.DefaultServeMux.ServeHTTP)\nlog.Fatal(http.ListenAndServe(\":8080\", nil))\n\n// Collect profiles:\n// go tool pprof http://localhost:8080/debug/pprof/profile?seconds=30\n// go tool pprof http://localhost:8080/debug/pprof/heap\n// go tool pprof http://localhost:8080/debug/pprof/goroutine\n\n// CLI profiling (in code)\nf, _ := os.Create(\"cpu.prof\")\npprof.StartCPUProfile(f)\ndefer pprof.StopCPUProfile()\n\n// Memory profile\nf, _ = os.Create(\"mem.prof\")\npprof.WriteHeapProfile(f)\nf.Close()" },
		"sync/atomic (Go 1.19+ Typed API)": { exp: "Go 1.19+ added typed atomic values: atomic.Int64, atomic.Value, etc. Learning Go recommends them over sync.Mutex for simple counters and flags. The zero value is ready to use, no initialization needed.", code: "var (\n\tcounter atomic.Int64\n\tloaded  atomic.Bool\n\tconfig  atomic.Pointer[Config]\n)\n\n// Counter\ncounter.Add(1)\nval := counter.Load()\ncounter.Store(42)\n\n// Bool\nloaded.Store(true)\nif loaded.Load() { fmt.Println(\"ready\") }\n\n// Pointer (atomic swap of config)\ncfg := &Config{Port: 8080}\nconfig.Store(cfg)\ncurrent := config.Load()\nfmt.Println(current.Port)\n\n// Swap + CompareAndSwap for lock-free algorithms\nold := config.Swap(&Config{Port: 9090})\nswapped := config.CompareAndSwap(old, &Config{Port: 3000})" }
	}
};
